package glitch

import data.glitch_lib

# Define sets for detection patterns
iam_admin_roles := {"Administrator", "Owner", "root", "Superuser", "SecurityAdmin", "NetworkAdmin", "SystemAdmin"}
permission_wildcards := {"*", "All", "ALL", "FullAccess"}
file_modes := {"0777", "777", "0755", "755", "0644", "644"}
unrestricted_cidrs := {"0.0.0.0/0", "::/0"}
container_privileges := {"hostPID", "hostNetwork", "privileged", "runAsRoot"}
privileged_capabilities := {"SYS_ADMIN", "NET_ADMIN", "ALL", "root"}

# Check for wildcard permissions in string values
check_wildcard_permission(value) {
    value.ir_type == "String"
    some wildcard in permission_wildcards
    contains(value.value, wildcard)
}

# Check for administrative roles in string values
check_admin_role(value) {
    value.ir_type == "String"
    some role in iam_admin_roles
    contains(value.value, role)
}

# Check for overly permissive file modes
check_file_mode(value) {
    value.ir_type == "String"
    some mode in file_modes
    value.value == mode
} else {
    value.ir_type == "Integer"
    value.value == 777
}

# Check for unrestricted CIDR blocks
check_unrestricted_cidr(value) {
    value.ir_type == "String"
    some cidr in unrestricted_cidrs
    value.value == cidr
}

# Check for container privilege flags
check_container_privilege(attr) {
    attr.ir_type == "Attribute"
    some priv in container_privileges
    contains(attr.name, priv)
    attr.value.ir_type == "Boolean"
    attr.value.value == true
} else {
    attr.ir_type == "Attribute"
    contains(attr.name, "capabilities")
    attr.value.ir_type == "Array"
    some cap in privileged_capabilities
    contains(attr.value.value, cap)
}

# Main detection rule for CWE-250
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for overly permissive IAM (wildcard permissions or admin roles)
    (check_wildcard_permission(attr.value) || check_admin_role(attr.value))

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Overly permissive IAM - Assignment of administrative or wildcard permissions to resources. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for excessive file system permissions
    check_file_mode(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Excessive file system permissions - Files with overly permissive access rights. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for unrestricted network access
    check_unrestricted_cidr(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Unrestricted network access - Overly permissive security group rules. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for container privilege escalation
    check_container_privilege(attr)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Container privilege escalation - Granting excessive privileges to containers. (CWE-250)"
